import unittest

from src.api.partner_adapter import to_partner_payload


class PartnerAdapterCase(unittest.TestCase):
    def test_payload_carries_the_order_identifier(self):
        payload = to_partner_payload(
            {"id": "o-1", "partner_id": "p-1", "amount_cents": 500, "created_at": "2026-01-01"}
        )
        self.assertEqual(payload["orderId"], "o-1")

    def test_whole_unit_partner_amount_is_converted_from_cents(self):
        payload = to_partner_payload(
            {"id": "o-2", "partner_id": "p-1", "amount_cents": 500, "created_at": "2026-01-01"}
        )
        self.assertEqual(payload["amount"], 5)

    def test_whole_unit_partner_rounds_instead_of_truncating(self):
        payload = to_partner_payload(
            {"id": "o-3", "partner_id": "p-7", "amount_cents": 1250, "created_at": "2026-01-01"}
        )
        self.assertEqual(payload["amount"], 13)

    def test_non_whole_unit_partner_amount_stays_in_cents(self):
        payload = to_partner_payload(
            {"id": "o-4", "partner_id": "p-2", "amount_cents": 1250, "created_at": "2026-01-01"}
        )
        self.assertEqual(payload["amount"], 1250)

    def test_settlement_currency_defaults_to_usd(self):
        payload = to_partner_payload(
            {"id": "o-5", "partner_id": "p-2", "amount_cents": 500, "created_at": "2026-01-01"}
        )
        self.assertEqual(payload["settlementCurrency"], "USD")

    def test_settlement_currency_is_passed_through(self):
        payload = to_partner_payload(
            {
                "id": "o-6",
                "partner_id": "p-2",
                "amount_cents": 500,
                "created_at": "2026-01-01",
                "settlement_currency": "EUR",
            }
        )
        self.assertEqual(payload["settlementCurrency"], "EUR")
